import{_ as l,c as i,o as e,ae as r}from"./chunks/framework.CHDT0Kbg.js";const b=JSON.parse(`{"title":"What's AviumUI (CN)","description":"","frontmatter":{},"headers":[],"relativePath":"upload/AviumUI.md","filePath":"upload/AviumUI.md"}`),t={name:"upload/AviumUI.md"};function o(h,a,n,u,s,d){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="what-s-aviumui-cn" tabindex="-1">What&#39;s AviumUI (CN) <a class="header-anchor" href="#what-s-aviumui-cn" aria-label="Permalink to &quot;What&#39;s AviumUI (CN)&quot;">​</a></h1><blockquote><p>✨ <strong>AviumUI 是一个由国内发起、基于 LineageOS 的定制项目</strong></p></blockquote><p>我们专注于用户所需、美观界面、原汁原味、强化功能等理念的发展。<br> 我们不断吸取来自各种 ROM 的优秀功能，同时创造独一无二的新奇体验。<br> 每一项功能的增加都经过深思熟虑，在开发难度与体验之间寻找最佳平衡。<br> 我们的目标是：<br><strong>提供真正需要、无缝融入日常使用习惯的系统体验。</strong> 😉</p><p>👉 <a href="./.html">Here is the English version</a></p><hr><h1 id="🎃-feature" tabindex="-1">🎃 Feature <a class="header-anchor" href="#🎃-feature" aria-label="Permalink to &quot;🎃 Feature&quot;">​</a></h1><hr><h2 id="🪙-nfc" tabindex="-1">🪙 NFC <a class="header-anchor" href="#🪙-nfc" aria-label="Permalink to &quot;🪙 NFC&quot;">​</a></h2><ul><li>新增 <strong>无感支付</strong><br> （通过识别 NFC 标签快速跳转到目标应用，目前已支持 <strong>支付宝、银联</strong>）</li></ul><hr><h2 id="🌙-moon-suggestion-使用场景上下文建议" tabindex="-1">🌙 Moon Suggestion（使用场景上下文建议） <a class="header-anchor" href="#🌙-moon-suggestion-使用场景上下文建议" aria-label="Permalink to &quot;🌙 Moon Suggestion（使用场景上下文建议）&quot;">​</a></h2><ul><li>在屏幕半暗时点击屏幕 → 建议 <strong>屏幕常亮</strong>\\</li><li>开启手电筒时 → 建议 <strong>快速关闭</strong>\\</li><li>连接到耳机时 → 推荐打开常用音乐 App\\</li><li>复制 App 链接时 → 推荐快速打开 App\\</li><li>复制快递单号 → 推荐快速查询\\</li><li>基于上下文使用浮动图标提供快捷操作</li></ul><hr><h2 id="🪄-avium-绝招" tabindex="-1">🪄 Avium 绝招 <a class="header-anchor" href="#🪄-avium-绝招" aria-label="Permalink to &quot;🪄 Avium 绝招&quot;">​</a></h2><h3 id="状态栏歌词" tabindex="-1">状态栏歌词 <a class="header-anchor" href="#状态栏歌词" aria-label="Permalink to &quot;状态栏歌词&quot;">​</a></h3><h3 id="音乐锁屏" tabindex="-1">音乐锁屏 <a class="header-anchor" href="#音乐锁屏" aria-label="Permalink to &quot;音乐锁屏&quot;">​</a></h3><ul><li>播放音乐时显示 <strong>黑胶唱片效果</strong>，增强沉浸感</li></ul><h3 id="ui-深度扩展" tabindex="-1">UI 深度扩展 <a class="header-anchor" href="#ui-深度扩展" aria-label="Permalink to &quot;UI 深度扩展&quot;">​</a></h3><ul><li>禁用锁屏压暗\\</li><li>启用桌面 <strong>全层级模糊效果</strong>\\</li><li>应用开闭时模糊底部图层\\</li><li>启动对应应用时允许 <strong>暂时禁用所有传感器 6 秒</strong>\\</li><li>长按屏幕导航条 → 启用 <strong>屏幕 OCR</strong>\\</li><li>允许用户遍历当前视图树以提取资源文件\\</li><li><strong>强制截图</strong> 功能</li></ul><hr><h2 id="🕒-万象时钟-全新锁屏系统" tabindex="-1">🕒 万象时钟（全新锁屏系统） <a class="header-anchor" href="#🕒-万象时钟-全新锁屏系统" aria-label="Permalink to &quot;🕒 万象时钟（全新锁屏系统）&quot;">​</a></h2><ul><li>引入全新的锁屏框架\\</li><li>新增 <strong>16 种全新锁屏样式</strong>\\</li><li>支持 <strong>高阶材质效果</strong>（Material You / Blur / 动态）</li></ul><hr><h2 id="🖼-景深壁纸" tabindex="-1">🖼 景深壁纸 <a class="header-anchor" href="#🖼-景深壁纸" aria-label="Permalink to &quot;🖼 景深壁纸&quot;">​</a></h2><ul><li>带来更加沉浸的壁纸体验\\</li><li>景深随视图变化产生动态效果</li></ul><hr><h1 id="📡-与其他设备互传" tabindex="-1">📡 与其他设备互传 <a class="header-anchor" href="#📡-与其他设备互传" aria-label="Permalink to &quot;📡 与其他设备互传&quot;">​</a></h1><h2 id="catshare-深度定制版本" tabindex="-1">CatShare（深度定制版本） <a class="header-anchor" href="#catshare-深度定制版本" aria-label="Permalink to &quot;CatShare（深度定制版本）&quot;">​</a></h2><ul><li>引入全新的选择界面\\</li><li>深度融合系统\\</li><li>与兼容「互传联盟」的设备直接共享文件</li></ul><hr><h1 id="🧩-多任务协同" tabindex="-1">🧩 多任务协同 <a class="header-anchor" href="#🧩-多任务协同" aria-label="Permalink to &quot;🧩 多任务协同&quot;">​</a></h1><h3 id="气泡小窗-增强版" tabindex="-1">气泡小窗（增强版） <a class="header-anchor" href="#气泡小窗-增强版" aria-label="Permalink to &quot;气泡小窗（增强版）&quot;">​</a></h3><ul><li>在原有气泡通知基础上支持直接启动应用</li></ul><h3 id="轻量小窗" tabindex="-1">轻量小窗 <a class="header-anchor" href="#轻量小窗" aria-label="Permalink to &quot;轻量小窗&quot;">​</a></h3><ul><li>通过手势快速唤醒\\</li><li>即用即走，轻量便捷</li></ul><h3 id="手势唤醒" tabindex="-1">手势唤醒 <a class="header-anchor" href="#手势唤醒" aria-label="Permalink to &quot;手势唤醒&quot;">​</a></h3><ul><li>从屏幕底部两侧向中心滑动即可唤醒菜单</li></ul><hr><h1 id="⚡-闪光速记" tabindex="-1">⚡ 闪光速记 <a class="header-anchor" href="#⚡-闪光速记" aria-label="Permalink to &quot;⚡ 闪光速记&quot;">​</a></h1><ul><li>快速记录复制内容并可立即编辑\\</li><li>让灵感不丢失、效率更顺手</li></ul><hr><h1 id="🧭-系统-ui-ux" tabindex="-1">🧭 系统 UI / UX <a class="header-anchor" href="#🧭-系统-ui-ux" aria-label="Permalink to &quot;🧭 系统 UI / UX&quot;">​</a></h1><h3 id="轻盈图标" tabindex="-1">轻盈图标 <a class="header-anchor" href="#轻盈图标" aria-label="Permalink to &quot;轻盈图标&quot;">​</a></h3><ul><li>更加清新、现代的图标设计</li></ul>',44)])])}const m=l(t,[["render",o]]);export{b as __pageData,m as default};
